WITH scored AS (SELECT *, LEAD(quantity) OVER (PARTITION BY product_id, order_id ORDER BY unit_price, id) AS next_quantity, LAG(unit_price) OVER (PARTITION BY product_id, order_id ORDER BY unit_price, id) AS prev_unit_price, ROW_NUMBER() OVER (PARTITION BY product_id, order_id ORDER BY unit_price, id) AS seq_no, AVG(unit_price) OVER (PARTITION BY product_id, order_id ORDER BY unit_price, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS unit_price_avg_5 FROM order_items) SELECT id, product_id, quantity, unit_price, next_quantity, seq_no FROM scored ORDER BY product_id DESC NULLS FIRST
